  "cue": "lean_forward_interest",
  "description": "Leans the upper body forward with open arms to express engagement and interest.",
  "movements": [
    {
      "type": "pose",
      "duration": 0.6,
      "parameters": {
        "pose": {
          "torso_height": "mid",
          "arm_position": "front",
          "gripper_orientation": "horizontal",
          "head": "center",
          "left_arm": "mirror",
          "elbow_bended": true,
          "z": 40
        }
      }
    },
    {
      "type": "path",
      "duration": 1.0,
      "parameters": {
        "path": {
          "mode": "ee",
          "shape": "line",
          "axis": "x",
          "distance": 0.1,
          "speed": 0.9,
          "side": "both"
        }
      }
    },
    {
      "type": "movement",
      "duration": 1.5,
      "parameters": {
        "movement": {
          "joints": [
            {
              "joint": "head",
              "axis": "tilt",
              "degrees": [
                0,
                -15
              ]
            }
          ],
          "repetition": 1,
          "speed": 0.8,
          "hold_time": 1.0
        }
      }
    }
  ]
}
